import csv
import json
import sys
import os
import datetime

FACT_MAPPING = {
    "lca.wage_105": {
        "offered wage": ("lca_disclosure", "WAGE_RATE_OF_PAY_FROM"),
        "prevailing wage": ("lca_disclosure", "PREVAILING_WAGE")
    },
    "lca.three_years": {
        "begin date": ("lca_disclosure", "BEGIN_DATE"),
        "end date": ("lca_disclosure", "END_DATE")
    }
}

def parse_date(d_str):
    d_str = d_str.strip()
    if not d_str:
        return ""
    if d_str.isdigit():
        excel_date = int(d_str)
        # Excel epoch starts at Dec 30, 1899. 1970-01-01 is 25569.
        delta = excel_date - 25569
        return (datetime.date(1970, 1, 1) + datetime.timedelta(days=delta)).strftime("%Y-%m-%d")
    if "/" in d_str:
        parts = d_str.split("/")
        if len(parts) == 3:
            if len(parts[2]) == 4:
                return f"{parts[2]}-{int(parts[0]):02d}-{int(parts[1]):02d}"
            elif len(parts[0]) == 4:
                return f"{parts[0]}-{int(parts[1]):02d}-{int(parts[2]):02d}"
    return d_str

def format_amount(a_str):
    a_str = a_str.strip()
    if not a_str:
        return ""
    a_str = a_str.replace(",", "").replace("$", "")
    return a_str

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    doc_data = {}
    for filename in os.listdir(packet_dir):
        if filename.endswith(".csv"):
            doc_name = filename[:-4]
            filepath = os.path.join(packet_dir, filename)

            records_by_entity = {}
            with open(filepath, "r", encoding="utf-8-sig") as f:
                reader = csv.DictReader(f)
                for row in reader:
                    entity = row.get("CASE_NUMBER", "")
                    if entity is None:
                        continue
                    entity = entity.strip()
                    if entity not in records_by_entity:
                        records_by_entity[entity] = []
                    records_by_entity[entity].append(row)
            doc_data[doc_name] = records_by_entity

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    results = {}
    for pair in manifest.get("pairs", []):
        rule_id, entity = pair.split("::", 1)
        facts = manifest.get("facts", {}).get(rule_id, [])

        pair_result = {}
        for fact in facts:
            if rule_id not in FACT_MAPPING or fact not in FACT_MAPPING[rule_id]:
                pair_result[fact] = "ABSENT"
                continue

            doc_name, field_name = FACT_MAPPING[rule_id][fact]

            if doc_name not in doc_data:
                pair_result[fact] = "ABSENT"
                continue

            records = doc_data[doc_name].get(entity, [])

            values = set()
            for row in records:
                val = row.get(field_name, "")
                if val is None:
                    val = ""
                val = val.strip()
                if val:
                    if "date" in fact.lower():
                        val = parse_date(val)
                    elif "wage" in fact.lower():
                        val = format_amount(val)
                    if val:
                        values.add(val)

            if len(values) == 0:
                pair_result[fact] = "ABSENT"
            elif len(values) == 1:
                pair_result[fact] = [list(values)[0], doc_name]
            else:
                pair_result[fact] = "CONFLICT"

        results[pair] = pair_result

    print(json.dumps(results, indent=2))

if __name__ == "__main__":
    main()

