import sys
import json
import csv
import os
import datetime

def excel_to_date(excel_date_str):
    excel_date_str = excel_date_str.strip()
    if not excel_date_str:
        return None
    try:
        # Excel's 1900 date system has a leap year bug for 1900.
        # For dates after Feb 28, 1900, the epoch to use in Python is Dec 30, 1899.
        excel_date = int(float(excel_date_str))
        dt = datetime.date(1899, 12, 30) + datetime.timedelta(days=excel_date)
        return dt.strftime("%Y-%m-%d")
    except ValueError:
        # Fallback if it's already a formatted string or unparseable
        return excel_date_str

def format_decimal(val):
    val = val.strip()
    if not val:
        return None
    return val

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    lca_path = os.path.join(packet_dir, 'lca_disclosure.csv')

    data = {}
    if os.path.exists(lca_path):
        with open(lca_path, 'r', encoding='utf-8-sig') as f:
            reader = csv.DictReader(f)
            for row in reader:
                case_number = row.get('CASE_NUMBER', '').strip()
                if not case_number:
                    continue
                if case_number not in data:
                    data[case_number] = []
                data[case_number].append(row)

    results = {}
    for pair in manifest.get('pairs', []):
        rule_id, entity = pair.split('::')
        facts = manifest.get('facts', {}).get(rule_id, [])

        pair_result = {}
        for fact in facts:
            values = set()

            if entity in data:
                for row in data[entity]:
                    val = None
                    if rule_id == 'lca.wage_105':
                        if fact == 'offered wage':
                            val = format_decimal(row.get('WAGE_RATE_OF_PAY_FROM', ''))
                        elif fact == 'prevailing wage':
                            val = format_decimal(row.get('PREVAILING_WAGE', ''))
                    elif rule_id == 'lca.three_years':
                        if fact == 'begin date':
                            val = excel_to_date(row.get('BEGIN_DATE', ''))
                        elif fact == 'end date':
                            val = excel_to_date(row.get('END_DATE', ''))

                    if val is not None:
                        values.add(val)

            if len(values) == 0:
                pair_result[fact] = "ABSENT"
            elif len(values) == 1:
                pair_result[fact] = [list(values)[0], "lca_disclosure"]
            else:
                pair_result[fact] = "CONFLICT"

        results[pair] = pair_result

    print(json.dumps(results, indent=2))

if __name__ == '__main__':
    main()

